import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{r as i,o as c,c as r,d as x,a as e,e as d,w as o,b as t,f as a}from"./app-12b563a2.js";const y="/assets/04-series-1-c665ed0f.svg",g={},f=e("div",{class:"hint-container tip"},[e("p",{class:"hint-container-title"},"读前须知"),e("p",null,"需要第 01、02 篇。本篇先在 CFG 上手算数据流传播，再用偏序、格和 Join 解释为什么这样合并；工作列表与不动点在下一篇展开，第 8 节的序对偶可选读。")],-1),h=a('<h2 id="_1-节点的输入、输出与初始状态" tabindex="-1"><a class="header-anchor" href="#_1-节点的输入、输出与初始状态" aria-hidden="true">#</a> 1. 节点的输入、输出与初始状态</h2><p>沿用上一例，<code>input()</code> 产生不可信数据，<code>sink(y)</code> 检查 y；集合 <code>{x,y}</code> 表示两者分别可能有污点。</p><p>本篇只处理单方法、局部变量、显式赋值与正常控制流。布尔参数不携带污点；调用不展开，<code>input</code> 与 <code>sink</code> 使用明确模型。第 04 篇的配套实现对未知语句直接报错，避免将缺失模型悄悄当作安全。</p><p>对每个节点 n，记录：</p><ul><li><strong>IN[n]</strong>：语句执行前可能有污点的变量。</li><li><strong>OUT[n]</strong>：语句执行后可能有污点的变量。</li><li><strong>可达标记</strong>：是否已有入口路径到达该节点。不可达与可达但集合为空分开保存。</li></ul><p>可以把 IN、OUT 看作语句前后的两块黑板：语句读取 IN、写出 OUT，再传给后继。</p><p>入口可达，IN 为空集；其他节点初始不可达。这里只在可达节点执行规则。</p><h2 id="_2-转移规则与合并规则" tabindex="-1"><a class="header-anchor" href="#_2-转移规则与合并规则" aria-hidden="true">#</a> 2. 转移规则与合并规则</h2>',8),p=e("code",null,"S\\{y}",-1),u=e("code",null,"∪",-1),b=e("code",null,"∅",-1),_=a(`<table><thead><tr><th style="text-align:left;">语句</th><th style="text-align:left;">输出规则</th><th style="text-align:left;">输入 <code>{x,y}</code> 时</th></tr></thead><tbody><tr><td style="text-align:left;"><code>flag := @parameter0</code>（参数绑定）</td><td style="text-align:left;"><code>S\\{flag}</code>：布尔参数不携带污点</td><td style="text-align:left;"><code>{x,y}</code></td></tr><tr><td style="text-align:left;"><code>x=input()</code></td><td style="text-align:left;"><code>S∪{x}</code></td><td style="text-align:left;"><code>{x,y}</code></td></tr><tr><td style="text-align:left;"><code>y=&quot;safe&quot;</code></td><td style="text-align:left;"><code>S\\{y}</code></td><td style="text-align:left;"><code>{x}</code></td></tr><tr><td style="text-align:left;"><code>y=x</code></td><td style="text-align:left;">先删除旧 y；若输入 S 含 x，再加入 y</td><td style="text-align:left;"><code>{x,y}</code></td></tr><tr><td style="text-align:left;">分支、跳转、sink、return</td><td style="text-align:left;">保留 S</td><td style="text-align:left;"><code>{x,y}</code></td></tr></tbody></table><p>复制规则必须读取<strong>赋值前</strong>的 x。例如 <code>x=x</code> 不会消除自己的污点；若先修改输入集合再检查右侧，就可能实现错。</p><p>本例是<strong>向前分析（forward analysis）</strong>：信息沿执行方向流动，从前驱的 OUT 计算后继的 IN。合并处取所有可达前驱的并集：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>IN[n]  = 所有可达前驱 OUT 的并集（入口另有边界条件）
OUT[n] = 当前语句的转移规则(IN[n])
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-把-n1—n7-算完" tabindex="-1"><a class="header-anchor" href="#_3-把-n1—n7-算完" aria-hidden="true">#</a> 3. 把 n1—n7 算完</h2><table><thead><tr><th style="text-align:left;">节点</th><th style="text-align:left;">语句简写</th><th style="text-align:left;">IN</th><th style="text-align:left;">OUT</th></tr></thead><tbody><tr><td style="text-align:left;">n1</td><td style="text-align:left;">参数绑定 flag</td><td style="text-align:left;"><code>∅</code></td><td style="text-align:left;"><code>∅</code></td></tr><tr><td style="text-align:left;">n2</td><td style="text-align:left;"><code>x=input()</code></td><td style="text-align:left;"><code>∅</code></td><td style="text-align:left;"><code>{x}</code></td></tr><tr><td style="text-align:left;">n3</td><td style="text-align:left;"><code>y=&quot;safe&quot;</code></td><td style="text-align:left;"><code>{x}</code></td><td style="text-align:left;"><code>{x}</code></td></tr><tr><td style="text-align:left;">n4</td><td style="text-align:left;"><code>if flag==false goto n6</code></td><td style="text-align:left;"><code>{x}</code></td><td style="text-align:left;"><code>{x}</code></td></tr><tr><td style="text-align:left;">n5</td><td style="text-align:left;"><code>y=x</code></td><td style="text-align:left;"><code>{x}</code></td><td style="text-align:left;"><code>{x,y}</code></td></tr><tr><td style="text-align:left;">n6</td><td style="text-align:left;"><code>sink(y)</code></td><td style="text-align:left;"><code>{x,y}</code></td><td style="text-align:left;"><code>{x,y}</code></td></tr><tr><td style="text-align:left;">n7</td><td style="text-align:left;">return</td><td style="text-align:left;"><code>{x,y}</code></td><td style="text-align:left;"><code>{x,y}</code></td></tr></tbody></table><p>关键在 n6：它既可以从 n4 直接到达，也可以从 n5 到达。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>n4 → n6 贡献 {x}
n5 → n6 贡献 {x,y}
IN[n6] = {x} ∪ {x,y} = {x,y}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只要一条路径让 y 带污点，汇合后就要保留这种可能性。这是 <strong>may 分析</strong>：判断某事实是否可能成立。</p><h2 id="_4-保证已初始化-为什么反而取交集" tabindex="-1"><a class="header-anchor" href="#_4-保证已初始化-为什么反而取交集" aria-hidden="true">#</a> 4. “保证已初始化”为什么反而取交集？</h2><p>换一个问题，用集合表示<strong>在所有到达路径上都已初始化的变量</strong>。下面是用于说明规则的伪代码；类似的未确定赋值读取在 Java 中会被编译器拒绝。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>声明 x、y，尚未赋值
x = 1
if flag:
    y = 2
使用 x、y
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th style="text-align:left;">到达汇合点的路径</th><th style="text-align:left;">保证已初始化</th></tr></thead><tbody><tr><td style="text-align:left;">执行 y=2</td><td style="text-align:left;"><code>{x,y}</code></td></tr><tr><td style="text-align:left;">跳过 y=2</td><td style="text-align:left;"><code>{x}</code></td></tr></tbody></table><p>只有 x 在两条路径上都有保证，所以合并为 <code>{x,y}∩{x}={x}</code>，<code>∩</code> 读作交集。这是 <strong>must 分析</strong>：要求某事实在所有所考虑的到达路径上成立。</p><p>污点并集放弃了“y 一定安全”，初始化交集放弃了“y 一定已初始化”，两者都损失信息。下面用偏序描述这种精度变化，再用格统一解释合并。</p><p>不可达前驱不应削弱初始化保证。尚未到达的节点与“可达但没有任何保证”不能混为一谈；第 7 节会结合顶、底元素解释这一点。</p><h2 id="_5-用偏序比较信息精度" tabindex="-1"><a class="header-anchor" href="#_5-用偏序比较信息精度" aria-hidden="true">#</a> 5. 用偏序比较信息精度</h2><p>先看同一对集合 <code>{x}</code>、<code>{x,y}</code>，但赋予它们不同含义：</p><table><thead><tr><th style="text-align:left;">分析</th><th style="text-align:left;"><code>{x}</code> 的含义</th><th style="text-align:left;"><code>{x,y}</code> 的含义</th><th style="text-align:left;">哪个提供更多信息</th></tr></thead><tbody><tr><td style="text-align:left;">可能有污点</td><td style="text-align:left;">只有 x 被列为可能有污点，排除了 y</td><td style="text-align:left;">x、y 都可能有污点</td><td style="text-align:left;"><code>{x}</code>，排除了更多可能性</td></tr><tr><td style="text-align:left;">保证已初始化</td><td style="text-align:left;">只保证 x</td><td style="text-align:left;">同时保证 x、y</td><td style="text-align:left;"><code>{x,y}</code>，提供了更多保证</td></tr></tbody></table><p>本系列固定约定：<strong>越往上越不精确。</strong> <code>a ⊑ b</code> 读作“a 在偏序下小于或等于 b”，表示 a 至少和 b 一样精确，也可以读成“a 不比 b 更粗”。</p><p>于是两种分析选择不同的集合关系：</p><table><thead><tr><th style="text-align:left;">集合的语义</th><th style="text-align:left;">本文的偏序定义</th><th style="text-align:left;">例子</th></tr></thead><tbody><tr><td style="text-align:left;">可能有污点</td><td style="text-align:left;"><code>A ⊑ B</code> 当且仅当 <code>A ⊆ B</code></td><td style="text-align:left;"><code>{x} ⊑ {x,y}</code></td></tr><tr><td style="text-align:left;">保证已初始化</td><td style="text-align:left;"><code>A ⊑ B</code> 当且仅当 <code>A ⊇ B</code></td><td style="text-align:left;"><code>{x,y} ⊑ {x}</code></td></tr></tbody></table><p><code>⊆</code> 读作“是……的子集”，允许相等；<code>⊇</code> 读作“是……的超集”。</p><p>**偏序（partial order）**须满足三个条件：</p><ol><li>自反性：<code>a ⊑ a</code>，读作“a 小于或等于它自己”。</li><li>反对称性：若 <code>a ⊑ b</code> 且 <code>b ⊑ a</code>，则 <code>a=b</code>。</li><li>传递性：若 <code>a ⊑ b</code> 且 <code>b ⊑ c</code>，则 <code>a ⊑ c</code>。</li></ol><p>偏序不要求任意两个元素都能比较。按包含关系，<code>{x}</code> 和 <code>{y}</code> 互不包含；它们排除了不同的可能性。**全序（total order）**还要求任意两个元素可比较，例如整数上的 <code>≤</code>。</p><h2 id="_6-幂集与格图怎么看" tabindex="-1"><a class="header-anchor" href="#_6-幂集与格图怎么看" aria-hidden="true">#</a> 6. 幂集与格图怎么看？</h2><p>令 <code>D={x,y}</code>。幂集（power set）<code>𝒫(D)</code> 就是 D 的所有子集组成的集合：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>𝒫({x,y}) = { ∅, {x}, {y}, {x,y} }
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>𝒫</code> 读作“幂集”，<code>∅</code> 是空集，外层花括号列出四个元素，其中每个元素本身也是集合。</p><p>下面两张图都使用这四个元素。线段连接相邻的可比较元素，<strong>向上表示按 <code>⊑</code> 变大，即信息变粗</strong>；它们不是程序执行箭头。</p><figure><img src="`+y+'" alt="可能污点与初始化保证的格：向上都更不精确" tabindex="0" loading="lazy"><figcaption>可能污点与初始化保证的格：向上都更不精确</figcaption></figure>',32),m={href:"https://github.com/Scrates1/Scrates1.github.io/blob/main/src/static-analysis/assets/04-series-1.mmd",target:"_blank",rel:"noopener noreferrer"},v=a('<p>污点图的顶部表示“x、y 都可能有污点”；初始化图的顶部表示“不能保证任何变量已初始化”。两者都是各自域中最粗的结果。</p><h2 id="_7-join-为什么这样合并" tabindex="-1"><a class="header-anchor" href="#_7-join-为什么这样合并" aria-hidden="true">#</a> 7. Join：为什么这样合并？</h2><p>对于 a、b，<strong>上界（upper bound）<strong>是同时位于它们上方或与它们相等的元素。上界中最小的一个叫</strong>最小上界（least upper bound）</strong>，也叫 Join，写作 <code>a ⊔ b</code>，读作“a Join b”。</p><p>Join 可看作“同时装下两边的最小盒子”。污点集合 <code>{x}</code> 与 <code>{y}</code> 的 Join 是 <code>{x,y}</code>：覆盖两边，又没有多加变量。</p><table><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">两个输入</th><th style="text-align:left;">Join 的结果</th><th style="text-align:left;">运算</th></tr></thead><tbody><tr><td style="text-align:left;">可能有污点</td><td style="text-align:left;"><code>{x}</code> 与 <code>{y}</code></td><td style="text-align:left;"><code>{x,y}</code></td><td style="text-align:left;">并集 <code>∪</code></td></tr><tr><td style="text-align:left;">保证已初始化</td><td style="text-align:left;"><code>{x}</code> 与 <code>{y}</code></td><td style="text-align:left;"><code>∅</code></td><td style="text-align:left;">交集 <code>∩</code></td></tr></tbody></table><p>对应地，**最大下界（greatest lower bound）**叫 Meet，记为 <code>⊓</code>，读作“a Meet b”。在污点图中是交集，在初始化图中是并集。这两种分析的路径汇合都使用上表的 Join。</p><p>每一对元素都存在 Join 和 Meet 的偏序集叫<strong>格（lattice）</strong>。若任意子集都有最小上界和最大下界，则是<strong>完全格（complete lattice）</strong>。有限格自动满足这一条件，本节的四元素幂集就是完全格。格保证任意两个结果都有唯一的最小上界，可用来定义合并。</p><p>最大元素写作 <code>⊤</code>，读作 top；最小元素写作 <code>⊥</code>，读作 bottom。污点域的顶、底分别是 D、∅，初始化保证域反过来。</p><p>污点域的 ∅ 表示没有变量可能有污点，可达的安全程序点也可以取得这个结果。本篇用独立的可达标记区分空集合与不可达；若将不可达加入整体状态域，它还需要自己的最小元素。</p><p>初始化保证按反向包含排序，底是 D。传统集合实现以 D 初始化非入口节点，再通过交集逐步撤销保证；入口则设置为实际已初始化的参数等。初始的 D 只是求解起点，保证要等求解完成才成立。若采用独立不可达状态，未到达节点暂不贡献，首次到达时接收前驱保证，后续再取交集。不能把所有节点预置为空集，否则交集会把真实的保证抹掉。</p><h2 id="_8-补充-为什么别的教材叫-meet" tabindex="-1"><a class="header-anchor" href="#_8-补充-为什么别的教材叫-meet" aria-hidden="true">#</a> 8. 补充：为什么别的教材叫 Meet？</h2><p>有些教材选择“越往上越精确”。把整个偏序反过来，就是<strong>序对偶（order duality）</strong>：原顺序的最小上界变成新顺序的最大下界。</p>',12),N={href:"https://courses.cs.cornell.edu/cs4120/2023sp/notes/iterative/index.html",target:"_blank",rel:"noopener noreferrer"},k=a('<p>以可能有污点为例：</p><table><thead><tr><th style="text-align:left;">约定（<code>⇔</code> 读作“当且仅当”）</th><th style="text-align:left;">精度向上怎样变化</th><th style="text-align:left;">路径汇合</th><th style="text-align:left;">运算名字</th></tr></thead><tbody><tr><td style="text-align:left;"><code>A⊑B ⇔ A⊆B</code></td><td style="text-align:left;">更粗</td><td style="text-align:left;">并集</td><td style="text-align:left;">Join</td></tr><tr><td style="text-align:left;"><code>A⊑B ⇔ A⊇B</code></td><td style="text-align:left;">更精确</td><td style="text-align:left;">并集</td><td style="text-align:left;">Meet</td></tr></tbody></table><p>阅读其他资料时，先确认 <code>⊑</code>、顶底元素和图的方向；运算名称会随顺序反转，可能污点的保守合并仍取并集。</p><h2 id="本篇要点" tabindex="-1"><a class="header-anchor" href="#本篇要点" aria-hidden="true">#</a> 本篇要点</h2><ul><li><strong>IN/OUT</strong> 保存语句前后的状态；可达标记区分“未到达”和“已到达但无污点”。</li><li><code>y=x</code> 覆盖旧 y，但必须读取赋值前的 x；自赋值保留污点。</li><li>可能污点取并集，初始化保证取交集；合并方式取决于事实的含义。</li><li><strong>偏序</strong>比较精度，本系列向上更粗；格上的 Join 是同时容纳两边结果的最小上界。</li><li>污点域的空集与不可达不同；初始化保证的空集也不能随意用作所有节点的初值。</li></ul><p>数据流方程和合并规则已经明确。遇到循环时，怎样安排重算，又怎样判断所有结果已经稳定？下一篇用工作列表的完整轨迹回答。</p>',6);function I(J,B){const l=i("RouterLink"),n=i("ExternalLinkIcon");return c(),r("div",null,[f,x(" more "),e("p",null,[d(l,{to:"/static-analysis/02-compilation-and-tools.html"},{default:o(()=>[t("第 02 篇")]),_:1}),t("建好了 CFG。现在为节点添加污点状态，计算哪些来源可能到达 sink。")]),h,e("p",null,[t("沿用"),d(l,{to:"/static-analysis/01-goals-and-abstraction.html"},{default:o(()=>[t("第 01 篇")]),_:1}),t("的转移规则。输入集合为 S，"),p,t(" 表示删除 y，"),u,t(" 为并集，"),b,t(" 为空集。")]),_,e("p",null,[e("a",m,[t("查看可编辑图源"),d(n)])]),v,e("p",null,[t("例如 "),e("a",N,[t("Cornell 的迭代数据流讲义"),d(n)]),t("使用从顶开始的下降迭代。读法应服从该资料自身的格约定。")]),k,e("p",null,[d(l,{to:"/static-analysis/02-compilation-and-tools.html"},{default:o(()=>[t("上一篇：02 编译流程与分析工具")]),_:1}),t(" · "),d(l,{to:"/static-analysis/04-worklist-and-fixed-point.html"},{default:o(()=>[t("下一篇：04 工作列表与不动点")]),_:1}),t(" · "),d(l,{to:"/static-analysis/"},{default:o(()=>[t("返回系列总览")]),_:1})])])}const T=s(g,[["render",I],["__file","03-dataflow-and-lattice.html.vue"]]);export{T as default};
